from itertools import product

def chromatic_number(edges, max_colors=5):
    n = 13
    # Try to color with up to max_colors colors
    for k in range(1, max_colors + 1):
        # Try all colorings
        for coloring in product(range(k), repeat=n):
            valid = True
            for u, v in edges:
                if coloring[u] == coloring[v]:
                    valid = False
                    break
            if valid:
                return k, coloring
    return None, None

