# Find shortest cycle using BFS from each vertex
def shortest_cycle(adj):
    n = len(adj)
    min_cycle = float('inf')

    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[v] >= dist[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len

    return min_cycle

girth = shortest_cycle(adj)
