# Let me also verify by finding actual cycles
def find_all_cycles(adj, max_len=6):
    cycles = []
    n = len(adj)

    for start in range(n):
        # DFS to find cycles
        stack = [(start, [start], {start})]
        while stack:
            u, path, visited = stack.pop()
            for v in adj[u]:
                if v == start and len(path) >= 3:
                    # Found a cycle
                    cycle = path[:]
                    if len(cycle) <= max_len:
                        cycles.append(cycle)
                elif v not in visited and v > start:  # Only consider v > start to avoid duplicates
                    stack.append((v, path + [v], visited | {v}))

    return cycles

